#!/usr/bin/env bash

## Taken from a 10-day Ollama learnig plan generated by OpenAI and Claude.

# model_shelf.sh -- Day 2 deliverable: sourceable helpers for curating an
# Ollama model shelf.  Works in bash and zsh.
#
#   source ./model_shelf.sh
#   shelf_pull core
#   shelf_size
#   shelf_gc
#   shelf_bench qwen2.5-coder:7b
#   shelf_which "summarize a long PDF"
#
# Edit the SHELF_* arrays below to match YOUR curated shelf (see the guide,
# section 7, and your Day 1 capacity numbers).

# ---------------------------------------------------------------------------
# Your curated shelf.  Format: "model | slot | one-line purpose"
# ---------------------------------------------------------------------------
SHELF_CORE=(
  "llama3.2:3b        | tiny      | fast chat, routing, first-pass classification"
  "llama3.1:8b        | workhorse | general chat, tool calling, RAG generation"
  "qwen2.5-coder:7b   | coder     | code generation, FIM, the Day 9 agent"
  "nomic-embed-text   | embedder  | embeddings for Day 7 search and Day 8 RAG"
)

SHELF_OPTIONAL=(
  "llama3.2:1b        | tiny      | autocomplete / ultra-cheap routing"
  "qwen2.5-coder:14b  | coder+    | harder refactors when speed is not critical"
  "deepseek-r1:8b     | reasoner  | multi-step reasoning, offline / overnight"
  "mxbai-embed-large  | embedder+ | higher-quality embeddings (larger, slower)"
)

OLLAMA_HOST_URL="${OLLAMA_HOST_URL:-http://127.0.0.1:11434}"

# ---------------------------------------------------------------------------
_shelf_models() {
  # $1 = core|optional|all  -> prints bare model names
  local set="${1:-core}" line name
  _emit() { for line in "$@"; do name="${line%%|*}"; echo "${name// /}"; done; }
  case "$set" in
    core)     _emit "${SHELF_CORE[@]}" ;;
    optional) _emit "${SHELF_OPTIONAL[@]}" ;;
    all)      _emit "${SHELF_CORE[@]}" "${SHELF_OPTIONAL[@]}" ;;
    *) echo "usage: _shelf_models core|optional|all" >&2; return 2 ;;
  esac
}

shelf_list() {
  # Pretty-print the curated shelf definition.
  echo "== CORE =="
  printf '%s\n' "${SHELF_CORE[@]}"
  echo
  echo "== OPTIONAL =="
  printf '%s\n' "${SHELF_OPTIONAL[@]}"
}

shelf_pull() {
  # Pull every model in a shelf set.  Skips ones already present.
  local set="${1:-core}" m present
  present="$(ollama list 2>/dev/null | awk 'NR>1{print $1}')"
  for m in $(_shelf_models "$set"); do
    if grep -qxF "$m" <<<"$present"; then
      echo "have   $m"
    else
      echo "pull   $m"
      ollama pull "$m"
    fi
  done
}

shelf_size() {
  # Per-model disk size (from `ollama list`) plus a real on-disk blob total.
  local store="${OLLAMA_MODELS:-$HOME/.ollama/models}"
  echo "model sizes (as reported by 'ollama list'):"
  ollama list | awk 'NR==1 || NR>1' | column -t
  echo
  if [ -d "$store/blobs" ]; then
    echo -n "actual blob store on disk: "
    du -sh "$store/blobs" 2>/dev/null | awk '{print $1}'
  fi
}

shelf_gc() {
  # Interactive: show local models NOT on the curated shelf and offer to remove.
  local keep m
  keep="$(_shelf_models all)"
  echo "Local models not on your curated shelf:"
  local orphans=()
  while read -r m; do
    [ -z "$m" ] && continue
    grep -qxF "$m" <<<"$keep" || orphans+=("$m")
  done < <(ollama list | awk 'NR>1{print $1}')

  if [ "${#orphans[@]}" -eq 0 ]; then
    echo "  (none -- shelf is clean)"
    return 0
  fi
  printf '  %s\n' "${orphans[@]}"
  echo
  printf 'Remove all of the above? [y/N] '
  read -r ans
  if [ "$ans" = "y" ] || [ "$ans" = "Y" ]; then
    for m in "${orphans[@]}"; do ollama rm "$m"; done
  else
    echo "nothing removed"
  fi
}

shelf_bench() {
  # Quick throughput probe for one model via the REST API.
  local model="${1:?usage: shelf_bench <model>}"
  python3 - "$model" "$OLLAMA_HOST_URL" <<'PY'
import json, sys, urllib.request
model, url = sys.argv[1], sys.argv[2]
payload = {"model": model, "prompt": "List five uses for a hash set.",
           "stream": False, "options": {"num_predict": 120, "temperature": 0}}
req = urllib.request.Request(url + "/api/generate",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json"})
d = json.loads(urllib.request.urlopen(req, timeout=180).read())
gen = d["eval_count"] / (d["eval_duration"]/1e9)
pr  = d["prompt_eval_count"] / (d["prompt_eval_duration"]/1e9)
ttft = (d.get("load_duration",0) + d["prompt_eval_duration"]) / 1e6
print(f"{model:<22} gen {gen:6.1f} tok/s   prompt {pr:8.1f} tok/s   TTFT {ttft:6.0f} ms")
PY
}

shelf_bench_all() {
  local set="${1:-core}" m
  for m in $(_shelf_models "$set"); do shelf_bench "$m"; done
}

shelf_which() {
  # Heuristic router: map a task description to a shelf slot.
  # CUSTOMISE these rules for your own shelf and workflow.
  local task="$*"
  local lc
  lc="$(printf '%s' "$task" | tr '[:upper:]' '[:lower:]')"
  case "$lc" in
    *embed*|*similarity*|*vector*|*semantic*)
      echo "embedder  -> nomic-embed-text" ;;
    *refactor*|*"write a"*|*implement*|*"fix the bug"*|*debug*|*code*|*function*|*regex*)
      echo "coder     -> qwen2.5-coder:7b   (14b if it's a large multi-file change)" ;;
    *classif*|*route*|*"yes or no"*|*label*|*"one word"*|*autocomplete*)
      echo "tiny      -> llama3.2:3b" ;;
    *reason*|*prove*|*"step by step"*|*"think through"*|*math*|*puzzle*)
      echo "reasoner  -> deepseek-r1:8b" ;;
    *summar*|*"rag"*|*"answer from"*|*"tool"*|*chat*|*explain*)
      echo "workhorse -> llama3.1:8b" ;;
    *)
      echo "workhorse -> llama3.1:8b   (default; no rule matched)" ;;
  esac
}

echo "model_shelf.sh loaded. commands: shelf_list shelf_pull shelf_size shelf_gc \
shelf_bench shelf_bench_all shelf_which"
